4	// FFT - Decimation in Time
5	// The produced FFT is scaled down by a factor of N to prevent overflow.
6	
7	// The Butterfly module that we are using assume that TF_WDTH is the same
8	// as X_WDTH.
9	// TF_WDTH must be the same as X_WDTH
10	
11	module dit
12	   #(
13	     // Length of FFT vector.
14	     parameter N = 16,
15	     // Base two log of N
16	     parameter NLOG2 = 4,
17	     // Number of bits in vector values (double this value for a complex number).
18	     parameter X_WDTH = 8,
19	      // Number of bits in twiddle factor values. (must be equal to X_WDTH at the moment)
20	     parameter TF_WDTH = 8,
21	     // Whether to run in debug mode.
22	     parameter DEBUGMODE = 0
23	     )
24	   (
25	    // The clock signal.
26	    input wire                clk,
27	    // Normally set to 1.  Set to 0 to reset module.
28	    input wire                rst_n,
29	    // Input value.
30	    // Within each complex number the real part is at the low end and the complex
31	    // at the high end.
32	    input wire [2*X_WDTH-1:0] in_x,
33	    // Set to 1 when new data placed in in_x.
34	    input wire                in_nd,
35	    // Output value.
36	    output reg [2*X_WDTH-1:0] out_x,
37	    // Set to 1 when new data is placed in out_x.
38	    output reg                out_nd,
39	    // Set to 1 when can't keep up with input data.
40	    output reg                overflow
41	    );
42	
43	   `define MSG_DEBUG(g) if(DEBUGMODE) $display("DEBUG : %m:", g)
44	   `define MSG_ERROR(g) $display("ERROR : %m:", g)
45	   
46	   /******************************/
47	   /* Define global data buffers */
48	   /******************************/
49	
50	   // Input buffer.
51	   reg [X_WDTH*2-1:0]           bufferin0[N-1:0];
52	   reg                          bufferin_full0_A;
53	   reg                          bufferin_full0_B;
54	   wire                         bufferin_full0;
55	   assign bufferin_full0 = bufferin_full0_A + bufferin_full0_B;
56	   reg [X_WDTH*2-1:0]           bufferin1[N-1:0];
57	   reg                          bufferin_full1_A;
58	   reg                          bufferin_full1_B;
59	   wire                         bufferin_full1;
60	   assign bufferin_full1 = bufferin_full1_A + bufferin_full1_B;
61	   reg                          bufferin_write_switch;
62	   reg                          bufferin_read_switch;
63	   wire                         bufferin_read_full;
64	   wire                         bufferin_write_full;
65	   assign bufferin_read_full = bufferin_read_switch?bufferin_full1:bufferin_full0;
66	   assign bufferin_write_full = bufferin_write_switch?bufferin_full1:bufferin_full0;
67	   // Working buffers.
68	   reg [X_WDTH*2-1:0]           bufferX[N-1:0];
69	   reg [X_WDTH*2-1:0]           bufferY[N-1:0];
70	   // Output buffer.
71	   reg [X_WDTH*2-1:0]           bufferout[N-1:0];
72	   // Whether the output buffer is full.
73	   // We have two registers since they are drive by different processes.
74	   // 'A' flips back and forth as the buffer is fulled.
75	   // 'B' flips back and forth as the buffer is emptied.
76	   reg                          bufferout_full_A;
77	   reg                          bufferout_full_B;
78	   wire                         bufferout_full;
79	   assign bufferout_full = bufferout_full_A + bufferout_full_B;
80	   // Whether the buffer contains good data. (i.e. not old)
81	   // Data should not be read from a buffer unless the correponding
82	   // updated value is 1.
83	   reg [N-1:0]                  updatedX;
84	   reg [N-1:0]                  updatedY;
85	
86	   /*******************************************************/
87	   /*                                                     */
88	   /* Define logic for receiving samples and placing in   */
89	   /* an input buffer.                                    */
90	   /*                                                     */
91	   /*******************************************************/
92	
93	   reg [NLOG2-1:0]              bufferin_addr;
94	   
95	   initial
96	     begin
97	        bufferin_addr <= {NLOG2{1'b0}};
98	        bufferin_full0_A <= 1'b0;
99	        bufferin_full1_A <= 1'b0;
100	        bufferin_write_switch <= 1'b0;
101	        overflow <= 1'b0;
102	     end
103	
104	   always @ (posedge clk or negedge rst_n)
105	     begin
106	        if (!rst_n)
107	          begin
108	             bufferin_addr <= {NLOG2{1'b0}};
109	             bufferin_full0_A <= 1'b0;
110	             bufferin_full1_A <= 1'b0;
111	             bufferin_write_switch <= 1'b0;
112	             overflow <= 1'b0;
113	          end
114	        else
115	          begin
116	             if (in_nd)
117	               begin
118	                  // Check for overflowed data.
119	                  if (bufferin_write_full)
120	                    overflow <= 1'b1;
121	                  if (bufferin_write_switch)
122	                    bufferin1[bufferin_addr] <= in_x;
123	                  else
124	                    bufferin0[bufferin_addr] <= in_x;
125	                  bufferin_addr <= bufferin_addr + 1;
126	                  if (&bufferin_addr)
127	                    begin
128	                       bufferin_write_switch <= ~bufferin_write_switch;
129	                       if (bufferin_write_switch)
130	                         bufferin_full1_A <= ~bufferin_full1_A;
131	                       else
132	                         bufferin_full0_A <= ~bufferin_full0_A;
133	                    end
134	               end
135	          end
136	     end
137	   
138	   /*******************************************************/
139	   /*                                                     */
140	   /* Define logic for emitting samples from the output   */
141	   /* buffer.                                             */
142	   /*                                                     */
143	   /*******************************************************/
144	
145	   reg [NLOG2-1:0]              bufferout_addr;
146	
147	   initial
148	     begin
149	        bufferout_addr <= {NLOG2{1'b0}};
150	        bufferout_full_B <= 1'b0;
151	        out_nd <= 1'b0;
152	     end
153	   
154	   always @ (posedge clk or negedge rst_n)
155	     begin
156	        if (!rst_n)
157	          begin
158	             bufferout_addr <= {NLOG2{1'b0}};
159	             bufferout_full_B <= 1'b0;
160	             out_nd <= 1'b0;
161	          end
162	        else
163	          begin
164	             if (bufferout_full)
165	               begin
166	                  out_x <= bufferout[bufferout_addr];
167	                  out_nd <= 1'b1;
168	                  bufferout_addr <= bufferout_addr + 1;
169	                  if (&bufferout_addr)
170	                    bufferout_full_B <= ~bufferout_full_B;
171	               end
172	             else
173	               out_nd <= 1'b0;
174	          end
175	     end
176	   
177	   /********************************************************/
178	   /*                                                      */
179	   /* Define FSM that passes data to the BF module.        */
180	   /*                                                      */
181	   /********************************************************/
182	
183	   reg [1:0] fsm_state;
184	   /* Define the control FSM states. */
185	   localparam  [1:0]  FSM_ST_INIT = 0;
186	   localparam  [1:0]  FSM_ST_IDLE = 1;
187	   localparam  [1:0]  FSM_ST_CALC = 2;
188	   localparam  [1:0]  FSM_ST_SEND = 3;
189	
190	   /*
191	    Calculation that determine which positions we should read from and write to
192	    for with the butterfly module.
193	    
194	    If we have a series x_n that we want to get the DFT of, X_k we can write X_k in
195	    terms of E_k and O_k where E_k and O_k are the DFTs of the even and odd components
196	    of x_n respectively.
197	
198	    for k<N/2  : X_k = E_k + exp(-2*pi*i*k/N)*O_k
199	    for k>=N/2 : X_k = E_{k-N/2} - exp(-2*pi*{k-N/2}/N)*O_{k-N/2}
200	    We use this relationship to calculate the DFT of x_n in a series of stages.  AFter the
201	    final stage the output is X_k.  After the second to last stage the output is an
202	    interleaving of E_k and O_k.
203	    
204	    At some general stage we have S interleaved series.
205	    
206	    So if X_k is the j'th series in a stage and P_n is the n'th output in that stage:
207	    
208	    X_k = P_{k*S+j}
209	    E_k is from a stage with 2*S series and it is in the j'th series in the stage
210	    O_k is from a stage with 2*S series and it is in the (S+j)'th series in stage
211	    Let Q_n be the n'th output of the stage before P.
212	    E_k = Q_{k*2*S+j}
213	    O_k = Q_{k*2*S+S+j}
214	
215	    Also let T_n = exp(-2*pi*i*n/M)
216	        
217	    M = N*S (total number of items in stage output)
218	    P_{k*S+j}     = Q_{2*k*S+j} + T_{k*S} * Q_{k*2*S+S+j}
219	    P_{k*S+j+M/2} = Q_{2*k*S+j} - T_{k*S} * Q_{k*2*S+S+j}
220	    
221	    We'll give these addresses names:
222	    out0_addr = k*S+j
223	    out1_addr = k*S+j+M/2
224	    in0_addr = 2*k*S+j
225	    in1_addr = 2*k*S+S+j
226	    
227	    Now we assume we know out0_addr and try to get efficient ways to calculate the
228	    other addresses.
229	
230	    out0_addr = k*S+j   (j ranges from 0 to S-1, and S is a multiple of two)
231	    If we look at out0_addr in binary the lowest log2(S) bits give the value of j
232	    and the highest log2(N) bits give the value for k.
233	    */
234	    
235	   // Number of series in the stage we are writing to.
236	   reg [NLOG2-1:0] S;
237	   // Contains a 1 for the bits that give j from out0_addr (i.e. which series).
238	   reg [NLOG2-1:0] series_bits;			
239	   reg [NLOG2-1:0] out0_addr;
240	   // Functions of the above 3 registers.
241	   wire [NLOG2-1:0] in0_addr;
242	   wire [NLOG2-1:0] in1_addr;
243	   wire [NLOG2-1:0] out1_addr;
244	   wire [NLOG2-2:0] tf_addr;
245	   
246	   //To get in0_addr we leave the lowest log2(S) bits alone but we shift the log2(N)
247	   //highest bits to the left (high is to left).
248	   
249	   //To get in1_addr we add S to in0_addr.
250	
251	   // out1_addr = out0+addr + M/2
252	   // We simply flip the highest bit from 0 to 1 which adds M/2.
253	   assign out1_addr = {1'b1, out0_addr[NLOG2-2:0]};
254	   // in0_addr = 2*k*S+j
255	   // (out0_addr & series_bits) = j
256	   // (out0_addr & ~series_bits) = k*S
257	   // Since the bits don't overlap we can add them with an OR.
258	   assign in0_addr = (out0_addr & series_bits) | ((out0_addr & ~series_bits)<<1);
259	   assign in1_addr = in0_addr + S;
260	   // (out0_addr & ~series_bits) = k*S
261	   assign tf_addr = out0_addr & ~series_bits;
262	   // Set to 1 when x_nd is set to 1 from the last BF calculation of the FFT.
263	   reg                          finished;
264	   // Which buffer we are reading from.
265	   // 1 if we are reading from X.
266	   // 0 if we are reading from Y.
267	   reg                          readbuf_switch;
268	   // We want readbuf_switch delayed by one step to send into the BF module.
269	   // The is because readbuf_switch may have changed since the values being
270	   // sent in were read.
271	   reg                          readbuf_switch_old;
272	   // Whether it is the first stage.
273	   wire                           first_stage;
274	   assign first_stage = (S == {1'b1,{NLOG2-1{1'b0}}});
275	   // Whether it is the last stage.
276	   wire                           last_stage;
277	   assign last_stage = (S == 1);
278	   // Inputs in to the BF module
279	   wire [2*X_WDTH-1:0]            in0;
280	   wire [2*X_WDTH-1:0]            in1;
281	   assign in0 = first_stage?(bufferin_read_switch?bufferin1[in0_addr]:bufferin0[in0_addr]):(readbuf_switch?bufferX[in0_addr]:bufferY[in0_addr]);
282	   assign in1 = first_stage?(bufferin_read_switch?bufferin1[in1_addr]:bufferin0[in1_addr]):(readbuf_switch?bufferX[in1_addr]:bufferY[in1_addr]);
283	   // Whether the two inputs have been updated.
284	   // Making sure we don't read before we have written.
285	   wire                         updated0;
286	   wire                         updated1;
287	   assign updated0 = first_stage?1:(readbuf_switch?updatedX[in0_addr]:updatedY[in0_addr]);
288	   assign updated1 = first_stage?1:(readbuf_switch?updatedX[in1_addr]:updatedY[in1_addr]);
289	   // Set to 1 when we want the twiddle factor module to return some new
290	   // twiddle factors.
291	   reg                          tf_addr_nd;
292	   // Tells the BF module that we are sending some data.
293	   reg                          x_nd;
294	   wire [2*TF_WDTH-1:0]         tf;
295	
296	   initial
297	     begin
298	        fsm_state <= FSM_ST_INIT;
299	        tf_addr_nd <= 1'b0;
300	        x_nd <= 1'b0;
301	        readbuf_switch <= 1'b0;
302	        bufferin_read_switch <= 1'b0;
303	        bufferin_full0_B <= 1'b0;
304	        bufferin_full1_B <= 1'b0;
305	     end
306	   
307	   // Create the FSM machine
308	   always @ (posedge clk or negedge rst_n)
309	     begin
310	        if (!rst_n)
311	          begin
312	             fsm_state <= FSM_ST_INIT;
313	             tf_addr_nd <= 1'b0;
314	             x_nd <= 1'b0;
315	             readbuf_switch <= 1'b0;
316	             bufferin_read_switch <= 1'b0;
317	             bufferin_full0_B <= 1'b0;
318	             bufferin_full1_B <= 1'b0;
319	          end
320	        else
321	          begin
322	             // Delay for readbuf_switch.
323	             readbuf_switch_old <= readbuf_switch;
324	             // Take note of when new data arrives.
325	             case (fsm_state)
326	               FSM_ST_INIT:
327	                 begin
328	                    // Starting a new FFT (we may not have received input data
329	                    // yet but we can still prepare.
330	                    `MSG_DEBUG("FSM_ST_INIT");
331				        out0_addr <= 0;
332				        // For the first stage we write to (the second stage) there
333	                    // are N/2 series.
334				        series_bits <= {NLOG2{1'b1}} >> 1;
335				        // There are N/2 series in that stage.
336				        S <= {1'b1,{NLOG2-1{1'b0}}};
337	                    // Tell twiddle factor module to calculate the first
338	                    //  twiddle factor.
339	                    tf_addr_nd <= 1'b1;
340	                    x_nd <= 1'b0;
341	                    finished <= 1'b0;
342	                    fsm_state <= FSM_ST_IDLE;
343	                 end // case: FSM_ST_INIT
344	               FSM_ST_IDLE:
345	                 begin
346	                    // Copy the input data into a buffer.
347	                    // If no input data is there we wait here until receiving
348	                    // input data.
349	                    // During the first step in this state the twiddle
350	                    // factor module will update the twiddle factor.
351	                    // During the last step in this state the BF module is
352	                    // sent it's first inputs.
353	                    `MSG_DEBUG("FSM_ST_IDLE");
354	                    tf_addr_nd <= 1'b0;
355	                    if (bufferin_read_full)
356	                      begin
357	                         fsm_state <= FSM_ST_CALC;
358	                         x_nd <= 1'b1;
359	                      end
360	                 end // case: FSM_ST_IDLE
361	               FSM_ST_CALC:
362	                 begin
363	                    `MSG_DEBUG("FSM_ST_CALC");
364	                    // In this state sections, series_bits, out0_addr and
365	                    // readbuf switch are updated so that we know where
366	                    // the BF module should read from and write to.
367	                    fsm_state <= FSM_ST_SEND;
368	                    tf_addr_nd <= 1'b1;
369	                    x_nd <= 1'b0;
370				        if (&(out1_addr))
371				          begin
372					         // We finished the last FFT stage.  Move onto the next.
373	                         `MSG_DEBUG("-------NEXT STAGE---------");
374	                         // If we're on the first stage then free up the input buffer
375	                         // for more input.
376	                         if (first_stage)
377	                           begin
378	                              `MSG_DEBUG("-Input Buffer No Longer Full-");
379	                              if (bufferin_read_switch)
380	                                bufferin_full1_B <= ~bufferin_full1_B;
381	                              else
382	                                bufferin_full0_B <= ~bufferin_full0_B;
383	                              bufferin_read_switch <= ~bufferin_read_switch;
384	                           end
385	                         // One less bit of in0_addr corresponds to which section
386	                         // it is in.
387					         series_bits <= series_bits >> 1;
388	                         // We have half as many sections as in the last stage.
389					         S <= S >> 1;
390					         out0_addr <= 0;
391	                         // We switch which buffers we are reading from and
392	                         // writing to.
393	                         readbuf_switch <= ~readbuf_switch;
394	                         // Mark the buffer we were previously reading from as
395	                         // not updated.  We will write to it now.
396	                         // Moved later so we drive from same process as we set.
397	                         /*
398	                         if (readbuf_switch)
399	                           updatedX <= {N{1'b0}};
400	                         else
401	                           updatedY <= {N{1'b0}};
402	                          */
403				          end
404				        else
405				          begin
406	                         `MSG_DEBUG("-------NEXT POSITION---------");
407					         // Otherwise we still have more sections to do at
408	                         // this position.
409					         out0_addr <= out0_addr + 1;
410				          end
411	                 end
412	               FSM_ST_SEND:
413	                 begin
414	                    `MSG_DEBUG("FSM_ST_SEND");
415	                    tf_addr_nd <= 1'b0;
416	                    // Wait in this state until the data we need to read is ready
417	                    // to go.
418	                    if (updated0 & updated1)
419	                      begin
420	                         x_nd <= 1'b1;
421	                         // If we have just sent data for the last BF calculation
422	                         // of the FFT calculation then go to the INIT state.
423	                         if (&(out1_addr) & (S==1))
424	                           begin
425	                              `MSG_DEBUG("--------FINISHED LAST STAGE---------");
426	                              fsm_state <= FSM_ST_INIT;
427	                              finished <= 1'b1;
428	                           end
429	                         else
430	                           fsm_state <= FSM_ST_CALC;
431	                      end
432	                    else
433	                      begin
434	                         `MSG_DEBUG("Waiting for data to be written.");
435	                      end
436	                 end
437	               default:
438	                 begin
439	                    fsm_state <= FSM_ST_INIT;
440	                 end
441	             endcase
442	          end              
443	     end
444	   
445	   /********************************************************/
446	   /*                                                      */
447	   /* Define logic that receives data from the BF.         */
448	   /*                                                      */
449	   /********************************************************/
450	
451	   // Outputs from the BF
452	   // The addresses where the output should be written to.
453	   wire [NLOG2-1:0]         out0_addr_z;
454	   wire [NLOG2-1:0]         out1_addr_z;
455	   // The real and imag components of the output.
456	   wire [2*X_WDTH-1:0]      z;
457	   // Set to 1 when the ZA is output.
458	   // On the step after ZB is output.
459	   wire                     z_nd;
460	   // Set to 1 for the last ZA of a FFT.
461	   wire                     finished_z;
462	   // Set to 1 if data is from the last stage.
463	   wire                     last_stage_z;
464	   // Indicates which buffer the inputs to the BF module were
465	   // read from.
466	   // 1 if read from X.
467	   // 0 if read from Y.
468	   wire 					readbuf_switch_z;
469	   // Delayed content of readbuf_swith_z;
470	   reg                      readbuf_switch_z_last;
471	   // Delayed content of out1_addr_z_old since we need to use
472	   // it after it may have changed.
473	   reg [NLOG2-1:0]          out1_addr_z_old;
474	   // The address to write the currently received BF output.
475	   wire [NLOG2-1:0]         out_addr_z;
476	   assign out_addr_z = (z_nd)?out0_addr_z:out1_addr_z_old;
477	   // A delayed z_nd.  Tells us when to expect ZB.
478	   reg                      z_nd_last;
479	   // For delaying variables.  It takes 2 steps to write the output data
480	   // to the buffer at which point we decide whether to write the data
481	   // to bufferout.  These registers are needed for that decision.
482	   reg                      finished_z_old[1:0];
483	   reg                      last_stage_z_old[0:0];
484	   reg                      readbuf_switch_z_old[1:0];
485	
486	   initial
487	     begin
488	        bufferout_full_A <= 1'b0;
489	        z_nd_last <= 1'b0;
490	     end
491	   
492	   always @ (posedge clk or negedge rst_n)
493		 begin
494			if (!rst_n)
495			  begin
496	             bufferout_full_A <= 1'b0;
497	             z_nd_last <= 1'b0;
498	          end
499	        else
500	          begin
501	             // Put updated reset here so we drive it from same process.
502	             if ((fsm_state == FSM_ST_CALC) & (&(out1_addr)))
503	               begin
504	                  if (readbuf_switch)
505	                    updatedX <= {N{1'b0}};
506	                  else
507	                    updatedY <= {N{1'b0}};
508	               end
509	             // Set all the delays.
510	             readbuf_switch_z_last <= readbuf_switch_z;
511	             finished_z_old[0] <= finished_z;
512	             finished_z_old[1] <= finished_z_old[0];
513	             last_stage_z_old[0] <= last_stage_z;
514	             readbuf_switch_z_old[0] <= readbuf_switch_z;
515	             readbuf_switch_z_old[1] <= readbuf_switch_z_old[0];
516	             out1_addr_z_old <= out1_addr_z;
517	             z_nd_last <= z_nd;
518	             if (finished_z_old[1])
519	               // We have filled the output buffer
520	               bufferout_full_A <= ~bufferout_full_A;
521	             // Write received data to the buffers and set updated flag.
522	             if (z_nd | z_nd_last)
523	               begin
524	                  if ((last_stage_z & z_nd)|(last_stage_z_old[0] & ~z_nd))
525	                    begin
526	                       bufferout[out_addr_z] <= z;
527	                    end
528			          else
529	                    begin
530	                       if ((readbuf_switch_z & z_nd)|(readbuf_switch_z_old[0] & ~z_nd))
531	                         begin
532			                    bufferY[out_addr_z] <= z;
533	                            updatedY[out_addr_z] <= 1'b1;
534	                         end
535			               else
536	                         begin
537			                    bufferX[out_addr_z] <= z;
538	                            updatedX[out_addr_z] <= 1'b1;
539	                         end
540	                    end
541	               end
542	          end
543	     end
544	
545	   /* Instantiate twiddle factor unit. */
546	   twiddlefactors
547	     twiddlefactors_0 (
548	                       .clk (clk),
549	                       .addr (tf_addr),
550	                       .addr_nd (tf_addr_nd),
551	                       .tf_out (tf)
552	                       );
553	   
554	   /* Instantiate the generic butterfly unit. */
555	   butterfly #(
556			.M_WDTH   (3 + 2*NLOG2),
557			.X_WDTH   (X_WDTH)
558			)
559	   butterfly_0 (
560					 .clk      (clk),
561					 .rst_n    (rst_n),
562					 .m_in     ({readbuf_switch_old, out0_addr, out1_addr, finished, last_stage}),
563					 .w        (tf),
564					 .xa       (in0),
565					 .xb       (in1),
566					 .x_nd     (x_nd),
